// ---------------------------------------------------------------------------
// Helpers. `norm` collapses the transcript's line breaks / trailing double spaces and un-escapes the markdown
// (split/join, never String.replace) so a printed cell can be matched inside a lifted span; the stored quote stays raw.
// ---------------------------------------------------------------------------
/** Markdown escapes of the transcript ("\>", "\<", "\+", "\-", "\=", "\[", "\]", "\.", "\!") → the printed character. */
export function deMd(s: string): string {
  return s.split('\\>').join('>').split('\\<').join('<').split('\\+').join('+').split('\\-').join('-').split('\\=').join('=')
    .split('\\[').join('[').split('\\]').join(']').split('\\.').join('.').split('\\!').join('!');
}
/** Whitespace-collapsed, markdown-unescaped view of a lifted span. */
export function norm(s: string): string {
  return deMd(s.replace(/\s+/g, ' ').trim());
}
/** Asserts that a printed cell string occurs verbatim (whitespace-collapsed) in its lifted span; returns it. */
export function cell(span: string, printed: string): string {
  if (!norm(span).includes(printed)) throw new Error(`printed cell not in span: "${printed}"`);
  return printed;
}
/** A Tab.-15 row "Grain 4/6 43 1400" → { cls: '4/6', pore: 43, surface: 1400 } (regex cut of the lifted line). */
export function tab15Row(line: string): { cls: string; pore: number; surface: number } {
  const m = norm(line).match(/^Grain (\d+\/\d+) (\d+) (\d+)$/);
  if (!m) throw new Error(`Tab. 15 row not parsed: ${norm(line)}`);
  return { cls: m[1], pore: Number(m[2]), surface: Number(m[3]) };
}
/** A §10.4.3 bullet "• submerged plants 6 – 10 plants;" → [6, 10]; "depending on type" → null. */
export function densityRange(line: string): [number, number] | null {
  const n = norm(line);
  const m = n.match(/(\d+) – (\d+) plants;/);
  if (m) return [Number(m[1]), Number(m[2])];
  if (n.includes('depending on type')) return null;
  throw new Error(`§10.4.3 bullet not parsed: ${n}`);
}

