// ---------------------------------------------------------------------------
// TABLE11 / TABLE12 — §10.2.2 Tab. 11 (L2666–L2753, controlled slow flow) and §10.2.3 Tab. 12 (L2788–L2862, controlled
// quick flow): one row per prod `filter_flow_direction` token (columns "vertical flow, continuous full-surface overflow" /
// "vertical flow, no overflow" / "horizontal flow"). The horizontal column prints "Individual verification no further
// information" for every parameter group → every numeric cell null, `individual_verification` true. Single-cell rows
// ("≥ 40 cm" / "≥ 50 cm", "≤ 16 mm" / "≤ 32 mm", "≤ 15% by weight", "≤ 2% / ≤ 0.5% by weight", "is mandatory", "10%
// deviation") span the two vertical columns (pdftotext layout, J-2). Water column: Tab. 11 "≥ 10 cm — Individual
// verification" (L2695), Tab. 12 "≥ 0 cm — Individual verification" (L2817). Feed rate: Tab. 11 Qmax 5 / 8 m3/(m2 x day)
// (L2743–L2749), Tab. 12 Qmin "≥ 15 m3/(m2 x day)" both (L2862; L2784–L2786 "must be operated with a feed rate of Qmin ≥
// 15 m3/(m2 x day). Smaller feed rates are permissible if the functionality of pool is ensured." — fll_naturteich-O-2).
// kf "≥ 10-4 m/s" / "≥ 10-3 m/s" = 10^-4 / 10^-3 (superscript dropped by the transcript). Policy `locked` (captions
// "Structural requirements"; L2661 / L2787 "Refer to Table 11 / 12 for information on the requirements.").
// ---------------------------------------------------------------------------
type FilterRow = { d: (typeof FLOW_DIRECTION_TOKENS)[number]; label: string; wc: number | null; feed: number | null; individual: boolean };
type FilterFixed = { layer: number; grain: number; oversize: number; fines: number; kf: number; tol: number };
type FilterPrinted = { layer: string; grain: string; fines: string; kf: string; wc: string; feed: string[]; individual: string };
function filterTable(code: 'TABLE11' | 'TABLE12', body: string, caption: string, cue: string, fixed: FilterFixed, printed: FilterPrinted, feedCol: 'feed_rate_qmax' | 'feed_rate_qmin', rowsIn: FilterRow[]): RegulationTable {
  const b = body;
  // pin the printed cells inside the lifted body
  for (const p of [printed.layer, printed.grain, printed.fines, printed.kf, printed.wc, '≤ 15% by weight', 'is mandatory', '10% deviation', 'no further information', ...printed.feed]) cell(b, p);
  const individual = `${cell(b, printed.individual)} ${cell(b, 'no further information')}`;
  const rows: RegulationRow[] = rowsIn.map((r, i) => ({
    row_key: r.d, keys: { flow_direction: r.d }, group_label: null, label_de: r.label, order_index: i,
    values: r.individual
      ? { water_column_min_cm: null, layer_min_cm: null, grain_max_mm: null, oversize_max_pct: null, fines_max_pct: null, frost_resistance_required: null, kf_min: null, tolerance_pct: null, [feedCol]: null, individual_verification: true, printed: individual }
      : { water_column_min_cm: r.wc, layer_min_cm: fixed.layer, grain_max_mm: fixed.grain, oversize_max_pct: fixed.oversize, fines_max_pct: fixed.fines, frost_resistance_required: true, kf_min: fixed.kf, tolerance_pct: fixed.tol, [feedCol]: r.feed, individual_verification: false,
          printed: `${r.wc == null ? '—' : printed.wc} · ${printed.layer} · ${printed.grain} · ≤ 15% by weight · ${printed.fines} · is mandatory · 10% deviation · ${printed.kf} · ${printed.feed[i] ?? printed.feed[0]}` },
    verbatim_quote: b,
  }));
  return { standard_code: STD, edition: ED, table_code: code, title_de: caption, clause_reference: code === 'TABLE11' ? '§10.2.2, Tab. 11' : '§10.2.3, Tab. 12', page_ref: code === 'TABLE11' ? '50' : '52',
    key_columns: ['flow_direction'],
    value_columns: [
      { name: 'water_column_min_cm', type: 'number', unit: 'cm' }, { name: 'layer_min_cm', type: 'number', unit: 'cm' }, { name: 'grain_max_mm', type: 'number', unit: 'mm' },
      { name: 'oversize_max_pct', type: 'number', unit: '% by weight' }, { name: 'fines_max_pct', type: 'number', unit: '% by weight' }, { name: 'frost_resistance_required', type: 'boolean' },
      { name: 'kf_min', type: 'number', unit: 'm/s' }, { name: 'tolerance_pct', type: 'number', unit: '%' }, { name: feedCol, type: 'number', unit: 'm³/(m²·d)' },
      { name: 'individual_verification', type: 'boolean' }, { name: 'printed', type: 'string' },
    ],
    override_policy: 'locked', override_quote: cue,
    verification_status: 'imported_unverified', rows }; // fll_naturteich-J-2
}
