// ---------------------------------------------------------------------------
// TABLE15 — Appendix 5 Tab. 15 (L4110–L4124): grain class → pore water [%] and surface [m2/m3]; one printed line per row
// (regex cut). Policy `anhaltswert`: L4111 "The values were determined using dolomite gravel" — L4122 "Size of the grain
// surface depends on its composition of grain sizes" (product data may replace the value with a reason).
// ---------------------------------------------------------------------------
const T15_LINES: Array<[(typeof GRAIN_CLASS_TOKENS)[number], string]> = [
  ['4_6', Q_T15_4_6], ['4_8', Q_T15_4_8], ['6_8', Q_T15_6_8], ['8_12', Q_T15_8_12], ['8_16', Q_T15_8_16], ['12_16', Q_T15_12_16], ['16_22', Q_T15_16_22], ['16_32', Q_T15_16_32], ['22_32', Q_T15_22_32],
];
export function table15AsTable(): RegulationTable {
  const rows: RegulationRow[] = T15_LINES.map(([token, line], i) => {
    const r = tab15Row(line);
    if (r.cls.split('/').join('_') !== token) throw new Error(`Tab. 15 token mismatch: ${token} vs ${r.cls}`);
    return { row_key: token, keys: { grain_class: token }, group_label: null, label_de: `Korn ${r.cls} mm`, order_index: i, values: { pore_water_pct: r.pore, surface_m2_m3: r.surface, grain_printed: r.cls }, verbatim_quote: line };
  });
  return { standard_code: STD, edition: ED, table_code: 'TABLE15', title_de: 'Korngrößen – Oberflächen (Tab. 15, Dolomitkies): Porenwasser und besiedelbare Oberfläche je Kornklasse', clause_reference: 'Appendix 5, Tab. 15', page_ref: '83',
    key_columns: ['grain_class'], value_columns: [{ name: 'pore_water_pct', type: 'number', unit: '%' }, { name: 'surface_m2_m3', type: 'number', unit: 'm²/m³' }, { name: 'grain_printed', type: 'string' }],
    override_policy: 'anhaltswert', override_quote: `${norm(Q_L4111)} — ${norm(Q_L4122)}`, // L4111 — L4122
    verification_status: 'md_verified', rows };
}

